export const revision = {
  carga: "tienda en línea",
  practicas: [
    { nombre: "Automatizar los cambios", pilar: "EXCELENCIA_OPERATIVA" },
    { nombre: "Establecer controles para detectar eventos de seguridad", pilar: "SEGURIDAD" },
    { nombre: "Planificar la recuperación ante fallos", pilar: "FIABILIDAD" },
    { nombre: "Elegir el tipo y el tamaño de los recursos según la carga", pilar: "EFICIENCIA_DEL_RENDIMIENTO" },
    { nombre: "Controlar el gasto a lo largo del tiempo", pilar: "OPTIMIZACION_DE_COSTOS" },
    { nombre: "Maximizar la utilización de los recursos", pilar: "SOSTENIBILIDAD" },
  ],
};

spec.code:
const practica = revision.practicas.find((p) => p.nombre === "Establecer controles para detectar eventos de seguridad");
assert.ok(practica, "debe existir la práctica de controles de seguridad");
assert.strictEqual(practica.pilar, "SEGURIDAD");

const pilares = ["EXCELENCIA_OPERATIVA", "SEGURIDAD", "FIABILIDAD", "EFICIENCIA_DEL_RENDIMIENTO", "OPTIMIZACION_DE_COSTOS", "SOSTENIBILIDAD"];
for (const practica of revision.practicas) {
  assert.ok(pilares.includes(practica.pilar), practica.nombre + " usa un pilar desconocido");
}

const esperado = {
  "Automatizar los cambios": "EXCELENCIA_OPERATIVA",
  "Planificar la recuperación ante fallos": "FIABILIDAD",
  "Elegir el tipo y el tamaño de los recursos según la carga": "EFICIENCIA_DEL_RENDIMIENTO",
  "Controlar el gasto a lo largo del tiempo": "OPTIMIZACION_DE_COSTOS",
  "Maximizar la utilización de los recursos": "SOSTENIBILIDAD",
};
for (const [nombre, pilar] of Object.entries(esperado)) {
  const practica = revision.practicas.find((p) => p.nombre === nombre);
  assert.ok(practica, "falta la práctica " + nombre);
  assert.strictEqual(practica.pilar, pilar);
}

