// Lista los pilares que faltan por revisar. Corrige su defecto principal.
export const PILARES = [
  "EXCELENCIA_OPERATIVA",
  "SEGURIDAD",
  "FIABILIDAD",
  "EFICIENCIA_DEL_RENDIMIENTO",
  "OPTIMIZACION_DE_COSTOS",
];

export function pilaresPendientes(revisados: string[]): string[] {
  return PILARES.filter((pilar) => !revisados.includes(pilar));
}

